-- Fetched verbatim (read-only) from the production migration history on 2026-11-27.
-- Applied to production on 2026-11-25 by the separate MDM backend; kept here so CLI history matches. Do not edit.
-- Independent MDM backend. No Enkai tables or policies are modified.
CREATE SCHEMA IF NOT EXISTS mdm;
REVOKE ALL ON SCHEMA mdm FROM PUBLIC;
CREATE TABLE IF NOT EXISTS mdm.tcp_requests (
 id text PRIMARY KEY, owner text NOT NULL, title text NOT NULL, kind text NOT NULL,
 filename text NOT NULL, file_key text NOT NULL, sha256 text NOT NULL, state text NOT NULL,
 revision integer NOT NULL DEFAULT 0, created text NOT NULL, updated text NOT NULL
);
CREATE INDEX IF NOT EXISTS tcp_requests_owner_updated ON mdm.tcp_requests(owner,updated);
CREATE TABLE IF NOT EXISTS mdm.workbook_rows (
 id text PRIMARY KEY, owner text NOT NULL, request_id text NOT NULL, base_sha text NOT NULL,
 sheet text NOT NULL, row_number integer NOT NULL, values_json text NOT NULL,
 provenance text NOT NULL, created text NOT NULL, audit_context text,
 row_revision integer NOT NULL DEFAULT 0,
 CONSTRAINT workbook_rows_position UNIQUE(owner,base_sha,sheet,row_number),
 CONSTRAINT workbook_rows_request_tab UNIQUE(owner,request_id,sheet)
);
CREATE TABLE IF NOT EXISTS mdm.workbook_audit (
 sequence bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id text NOT NULL UNIQUE, owner text NOT NULL, actor_id text NOT NULL, action text NOT NULL,
 occurred_at text NOT NULL, base_sha text NOT NULL, record_id text, sheet text,
 row_number integer, request_id text, reason text NOT NULL, method text NOT NULL,
 outcome text NOT NULL, before_values text, after_values text, columns_json text,
 revision_before integer, revision_after integer, related_event text, details text NOT NULL
);
CREATE INDEX IF NOT EXISTS workbook_audit_owner_sequence ON mdm.workbook_audit(owner,sequence);
CREATE INDEX IF NOT EXISTS workbook_audit_record ON mdm.workbook_audit(owner,record_id,sequence);
CREATE TABLE IF NOT EXISTS mdm.initiatives (
 id text PRIMARY KEY, owner text NOT NULL, name text NOT NULL, template_id text,
 selections_json text NOT NULL, revision integer NOT NULL DEFAULT 0,
 created_at text NOT NULL, updated_at text NOT NULL, UNIQUE(owner,name)
);
CREATE INDEX IF NOT EXISTS initiatives_owner_updated ON mdm.initiatives(owner,updated_at);
CREATE TABLE IF NOT EXISTS mdm.initiative_templates (
 id text PRIMARY KEY, owner text NOT NULL, name text NOT NULL, selections_json text NOT NULL,
 created_at text NOT NULL, updated_at text NOT NULL, UNIQUE(owner,name)
);
CREATE INDEX IF NOT EXISTS initiative_templates_owner_updated ON mdm.initiative_templates(owner,updated_at);
-- The authenticated Supabase ID is mapped to its old owner ID only after a
-- verified migration. Historical actor_id values are retained unchanged.
CREATE TABLE IF NOT EXISTS mdm.allowed_users (
 auth_user_id uuid PRIMARY KEY REFERENCES auth.users(id),
 legacy_owner_id text UNIQUE,
 enabled boolean NOT NULL DEFAULT true
);
ALTER TABLE mdm.tcp_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE mdm.workbook_rows ENABLE ROW LEVEL SECURITY;
ALTER TABLE mdm.workbook_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE mdm.initiatives ENABLE ROW LEVEL SECURITY;
ALTER TABLE mdm.initiative_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE mdm.allowed_users ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE role_name text;
BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN
   EXECUTE format('REVOKE ALL ON SCHEMA mdm FROM %I',role_name);
   EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA mdm FROM %I',role_name);
   EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA mdm FROM %I',role_name);
  END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
  GRANT USAGE ON SCHEMA mdm TO service_role;
  GRANT ALL ON ALL TABLES IN SCHEMA mdm TO service_role;
  GRANT ALL ON ALL SEQUENCES IN SCHEMA mdm TO service_role;
 END IF;
END $$;
-- Storage has no client policies: server functions alone read/write MDM files.
INSERT INTO storage.buckets(id,name,public,file_size_limit)
VALUES('mdm-private','mdm-private',false,52428800)
ON CONFLICT(id) DO UPDATE SET public=false;

